head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.srchType = "";

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        // 초기화함수
        scwin.init();

        await scwin.listSync();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09047.onpageload" });
    }
};

/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    scwin.srchType = $c.data.getParameter("srchType");
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.btn_confirm_onclick = async function() {
    try {
        await scwin.confirm();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF09047.btn_confirm_onclick" });
    }
};

/**
 * @method
 * @name img_rightarr_onclick
 * @description img_rightarr 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_rightarr_onclick = function (e) {
    try {
        scwin.add();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09047.img_rightarr_onclick" });
    }
};

/**
 * @method
 * @name grd_list_oncelldblclick
 * @description grd_list 셀 더블클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_list_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.add();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09047.grd_list_oncelldblclick" });
    }
};

/**
 * @method
 * @name grd_selList_oncelldblclick
 * @description grd_selList 셀 더블클릭 이벤트
 * @param {Number} rowIndex 행 인덱스
 * @param {Number} columnIndex 열 인덱스
 * @param {String} columnId 컬럼 id
 * @returns {void}
 * @hidden N
 */
scwin.grd_selList_oncelldblclick = function (rowIndex, columnIndex, columnId) {
    try {
        scwin.del();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09047.grd_selList_oncelldblclick" });
    }
};

/**
 * @method
 * @name img_leftarr_onclick
 * @description img_leftarr 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_leftarr_onclick = function (e) {
    try {
        scwin.del();
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDSTF09047.img_leftarr_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 목록 조회
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.listSync = async function() {
    let actionUrl = "";
    if("pfAll" === scwin.srchType){
        actionUrl = "/api/listing/common/pop/isu/select-list-pfcode";
    }

    const sbmOptions = {
        id : "sbm_List",
        method: "get",
        action : actionUrl,
        target : "dlt_list=body",
        isProcessMsg : false
    };

    await $c.sbm.executeDynamic(sbmOptions);
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name add
 * @description 조회 목록의 선택 행을 선택 목록에 추가(중복이면 무시)
 * @returns {void}
 * @hidden N
 */
scwin.add = function() {
    const selRowIndex = dlt_list.getRowPosition();
    if (selRowIndex < 0) {
        return;
    }
    const vValue = dlt_list.getCellData(selRowIndex, "isuCd");
    for (let i = 0; i < dlt_selList.getRowCount(); i++) {
        if (dlt_selList.getCellData(i, "isuCd") === vValue) {
            return;
        }
    }

    const rowPosition = dlt_selList.getRowCount();
    dlt_selList.insertRow();

    dlt_selList.setCellData(rowPosition, "isuCd", vValue);
    dlt_selList.setCellData(rowPosition, "isuNm", dlt_list.getCellData(selRowIndex, "isuNm"));
    dlt_selList.setCellData(rowPosition, "isurCd", dlt_list.getCellData(selRowIndex, "isurCd"));
    dlt_selList.setCellData(rowPosition, "isurNm", dlt_list.getCellData(selRowIndex, "isurNm"));
    dlt_selList.setCellData(rowPosition, "comNm", dlt_list.getCellData(selRowIndex, "comNm"));
    dlt_selList.setCellData(rowPosition, "listDd", dlt_list.getCellData(selRowIndex, "listDd"));
};

/**
 * @method
 * @name del
 * @description 선택 목록에서 현재 행 삭제
 * @returns {void}
 * @hidden N
 */
scwin.del = function() {
    const rowPos = dlt_selList.getRowPosition();
    if (rowPos < 0) {
        return;
    }
    dlt_selList.removeRow(rowPos);
};

/**
 * @method
 * @name confirm
 * @description 선택 목록을 오프너에 전달하고 팝업을 닫는다
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function() {
    const resObj = dlt_selList.getInsertedJSON();
    $c.win.closePopup(resObj);
};
